dnd_labels = ['No Discount', 'With Discount']
dnd_revenue = safe_list(disc_vs_nondisc['revenue'].tolist())
dnd_margin = safe_list(disc_vs_nondisc['avg_margin'].tolist())
dnd_avg_qty = safe_list(disc_vs_nondisc['avg_qty'].tolist())

# ──────────────────────────────────────────────
# 5. Customer Behavior & Loyalty Insights
# ──────────────────────────────────────────────
customer_perf = df.groupby('customer_id').agg(
