avg_orders_per_customer = safe_val(customer_perf['orders'].mean())
avg_customer_revenue = safe_val(customer_perf['revenue'].mean())
avg_customer_profit = safe_val(customer_perf['profit'].mean())

# Customer segments by order frequency
freq_bins = [0, 1, 3, 5, 10, 100]
freq_labels_list = ['1 order', '2-3 orders', '4-5 orders', '6-10 orders', '10+ orders']
