import pandas as pd
import json
import math

# Load data
df = pd.read_csv('/app/benchmark/data.csv', parse_dates=['order_date'])

# Ensure numeric types
for col in ['quantity', 'unit_price', 'discount', 'revenue', 'cost', 'profit']:
    df[col] = pd.to_numeric(df[col], errors='coerce')

# Drop rows with any NaN in critical columns
df = df.dropna(subset=['order_date', 'revenue', 'profit', 'quantity', 'unit_price', 'discount'])

# Derived columns
df['year'] = df['order_date'].dt.year
df['month'] = df['order_date'].dt.month
df['quarter'] = df['order_date'].dt.quarter
df['year_month'] = df['order_date'].dt.to_period('M').astype(str)
df['year_quarter'] = df['year'].astype(str) + '-Q' + df['quarter'].astype(str)
df['profit_margin'] = df.apply(lambda r: (r['profit'] / r['revenue'] * 100) if r['revenue'] != 0 else 0, axis=1)
df['has_discount'] = df['discount'] > 0

# Helper for safe JSON serialization (handle NaN/Inf)
def safe_val(v):
    if isinstance(v, float) and (math.isnan(v) or math.isinf(v)):
        return 0
    return round(v, 2)

def safe_list(lst):
    return [safe_val(x) for x in lst]

# ──────────────────────────────────────────────
# KPIs
# ──────────────────────────────────────────────
total_revenue = safe_val(df['revenue'].sum())
total_profit = safe_val(df['profit'].sum())
avg_profit_margin = safe_val(df['profit_margin'].mean())
avg_order_value = safe_val(df['revenue'].mean())
discount_util_rate = safe_val(df['has_discount'].mean() * 100)
total_orders = len(df)

# Year-over-year
df_2023 = df[df['year'] == 2023]
df_2024 = df[df['year'] == 2024]
rev_2023 = safe_val(df_2023['revenue'].sum())
rev_2024 = safe_val(df_2024['revenue'].sum())
profit_2023 = safe_val(df_2023['profit'].sum())
profit_2024 = safe_val(df_2024['profit'].sum())
yoy_rev_growth = safe_val((rev_2024 - rev_2023) / rev_2023 * 100) if rev_2023 else 0
yoy_profit_growth = safe_val((profit_2024 - profit_2023) / profit_2023 * 100) if profit_2023 else 0
orders_2023 = len(df_2023)
orders_2024 = len(df_2024)

# ──────────────────────────────────────────────
# 1. Sales Trends Over Time
# ──────────────────────────────────────────────
monthly = df.groupby('year_month').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean')
).reset_index().sort_values('year_month')

monthly_labels = monthly['year_month'].tolist()
monthly_revenue = safe_list(monthly['revenue'].tolist())
monthly_profit = safe_list(monthly['profit'].tolist())
monthly_orders = safe_list(monthly['orders'].tolist())
monthly_margin = safe_list(monthly['avg_margin'].tolist())

# Quarterly
quarterly = df.groupby('year_quarter').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean')
).reset_index().sort_values('year_quarter')

quarterly_labels = quarterly['year_quarter'].tolist()
quarterly_revenue = safe_list(quarterly['revenue'].tolist())
quarterly_profit = safe_list(quarterly['profit'].tolist())
quarterly_orders = safe_list(quarterly['orders'].tolist())

# ──────────────────────────────────────────────
# 2. Product & Category Performance
# ──────────────────────────────────────────────
product_perf = df.groupby('product_id').agg(
    revenue=('revenue', 'sum'),
    profit=('profit', 'sum'),
    orders=('order_id', 'count'),
    avg_margin=('profit_margin', 'mean'),
    avg_qty=('quantity', 'mean'),
    avg_unit_price=('unit_price', 'mean')
).reset_index().sort_values('revenue', ascending=False)

top10_products = product_perf.head(10)
